import { z } from "zod";
import { LEVELS } from "@/domain/model";
import { SPELLING_CATEGORIES } from "@/domain/spelling/categories";

/**
 * The open-data library (DECISIONS "Open data"): compact JSON chunks in
 * public/content/v1, generated by `npm run content:build`. The hand-written
 * bank (src/data/words) stays bundled; the library only adds words that are
 * not in it. Chunks are fetched on demand and validated with these schemas,
 * because anything read over the network is external input.
 */

const lowerWord = z.string().regex(/^[a-z]+(?:['-][a-z]+)*$/, "lower-case English word");

const arabic = z
  .string()
  .min(1)
  .max(60)
  .refine((s) => /[؀-ۿ]/.test(s), "must contain Arabic")
  .refine((s) => !/[A-Za-z]/.test(s), "Arabic hint must not contain Latin letters");

/** Extra data a library word may carry. */
export const libraryExtraSchema = z
  .object({
    /** British spelling (VarCon), when it differs. */
    uk: lowerWord.optional(),
    /** Homophones (CMUdict), for "homophones" words only. */
    c: z.array(lowerWord).min(1).max(3).optional(),
    /** Reviewed Arabic hint (phase D), for the most frequent words. */
    ar: arabic.optional(),
    /** Id of the example sentence in the sentence chunks (phase C). */
    ex: z.string().regex(/^(t|o)\d+$/).optional(),
  })
  .strict();
export type LibraryExtra = z.infer<typeof libraryExtraSchema>;

/** [word, frequency rank, extra?] */
export const libraryRowSchema = z.union([z.tuple([lowerWord, z.number().int().positive()]), z.tuple([lowerWord, z.number().int().positive(), libraryExtraSchema])]);
export type LibraryRow = z.infer<typeof libraryRowSchema>;

export const wordChunkSchema = z
  .object({
    level: z.enum(LEVELS),
    words: z.partialRecord(z.enum(SPELLING_CATEGORIES), z.array(libraryRowSchema)),
  })
  .strict();
export type WordChunk = z.infer<typeof wordChunkSchema>;

const fileEntry = z
  .object({
    path: z.string().regex(/^[A-Za-z0-9-]+(\.[a-f0-9]{10})?\.(json|tsv)$/),
    sha256: z.string().regex(/^[a-f0-9]{64}$/),
    bytes: z.number().int().positive(),
  })
  .strict();
export type ManifestFile = z.infer<typeof fileEntry>;

export const manifestSchema = z
  .object({
    $comment: z.string().optional(),
    version: z.literal(1),
    /** Words by level: "words-A1" … "words-C1". Sentences arrive in phase C. */
    files: z.record(z.string().regex(/^[A-Za-z0-9-]+$/), fileEntry),
  })
  .strict();
export type Manifest = z.infer<typeof manifestSchema>;
